/* R7B-G1B12 — strict offline-only decoder for OWNED synthetic Vector 0.53.0 events.
 * No Docker, Vector process, transport, filesystem or arbitrary event ingestion.
 * The old R7B parser is intentionally unchanged. Only the canonical synthetic
 * wire layout generated by r7b-vector053-wire-contract.mjs is accepted.
 * timeNano stays a decimal string; BigInt is used for exact verification.
 */

const ID = 'a'.repeat(64);
const NAME = 'r7b-synthetic-fixture';
const LABEL = 'LAB_ONLY';
const MAX_SECONDS = 2147483647;
const MAX_I64 = 9223372036854775807n;
const NANOS_PER_SECOND = 1000000000n;
const MAX_CHUNK = 2048;
const MAX_RECORD = 768;
const MAX_TOTAL_BYTES = 65536;
const MAX_RECORDS = 100;
const MAX_PENDING = 8;
const FATAL_UTF8 = new TextDecoder('utf-8', {fatal:true});
const CANONICAL = /^\{"Type":"container","Action":"(start|unpause|die|pause)","Actor":\{"ID":"(a{64})","Attributes":\{"name":"r7b-synthetic-fixture","r7b\.lab\.owner":"LAB_ONLY"\}\},"time":([1-9][0-9]*),"timeNano":([1-9][0-9]*)\}$/;
const fail = code => { throw new Error('R7B12_BLOCKED_' + code); };

/** Decode exactly one canonical synthetic event (without its NDJSON newline).
 * The i64 is never parsed through JS Number or JSON.parse. Returning decimal
 * text is intentional: it cannot be silently rounded by callers.
 */
export function decodeR7B12NumericEventLine(line) {
  if (!Buffer.isBuffer(line) || line.length < 1 || line.length > MAX_RECORD)
    fail('EVENT_SIZE');
  let value;
  try { value = FATAL_UTF8.decode(line); }
  catch { fail('EVENT_UTF8'); }
  const match = CANONICAL.exec(value);
  if (!match || match[2] !== ID) fail('EVENT_WIRE');
  const [, action, , secondsToken, nanoToken] = match;
  if (secondsToken.length > 10 || nanoToken.length > 19) fail('TIME_RANGE');
  const time = Number(secondsToken);
  if (!Number.isSafeInteger(time) || time < 2 || time > MAX_SECONDS)
    fail('TIME_RANGE');
  // BigInt converts the raw lexical digits, not a rounded IEEE-754 value.
  const timeNano = BigInt(nanoToken);
  if (timeNano > MAX_I64 || timeNano / NANOS_PER_SECOND !== BigInt(time))
    fail('TIME_NANO');
  return Object.freeze({
    type:'container', action, actorId:ID, name:NAME,
    label:LABEL, time, timeNano:nanoToken,
    subsecondNano:Number(timeNano % NANOS_PER_SECOND),
    timeNanoWireType:'JSON_INT64_NUMBER',
    origin:'R7B_PUBLIC_SYNTHETIC_ONLY'
  });
}

/** In-memory NDJSON fragment decoder. Each push is atomic: no valid event in
 * a chunk containing a malformed event is published. A full pending queue
 * applies backpressure without accepting or consuming the next chunk.
 */
export function createR7B12NumericEventStream() {
  let state = 'ACTIVE';
  let carry = Buffer.alloc(0);
  let pending = [];
  let bytesReceived = 0;
  let records = 0;
  const status = () => Object.freeze({state, bytesReceived, records,
    pending:pending.length, buffered:carry.length});
  const wipe = () => {carry.fill(0); carry = Buffer.alloc(0); pending = [];};
  const blocked = code => {wipe(); state='FAILED'; fail(code);};
  return Object.freeze({
    push(chunk) {
      if (state !== 'ACTIVE') fail('NOT_ACTIVE');
      if (!Buffer.isBuffer(chunk) || chunk.length < 1 || chunk.length > MAX_CHUNK)
        blocked('CHUNK');
      if (pending.length === MAX_PENDING) fail('BACKPRESSURE');
      if (bytesReceived + chunk.length > MAX_TOTAL_BYTES)
        blocked('TOTAL_BYTES');
      if (carry.length + chunk.length > MAX_CHUNK + MAX_RECORD)
        blocked('CHUNK_BUFFER');
      const joined = Buffer.concat([carry, chunk]);
      const newlyDecoded = [];
      let offset = 0;
      try {
        while (true) {
          const end = joined.indexOf(10, offset);
          if (end < 0) break;
          if (end === offset || end - offset > MAX_RECORD) fail('EVENT_SIZE');
          newlyDecoded.push(decodeR7B12NumericEventLine(joined.subarray(offset,end)));
          offset = end + 1;
        }
        if (joined.length - offset > MAX_RECORD) fail('EVENT_SIZE');
      } catch (err) {
        joined.fill(0);
        blocked('INVALID_' + String(err?.message || 'UNKNOWN').replace(/^R7B12_BLOCKED_/,'').replace(/[^A-Z0-9_]/g,'_').slice(0,60));
      }
      if (pending.length + newlyDecoded.length > MAX_PENDING) {
        joined.fill(0);
        fail('BACKPRESSURE'); // Atomic retry: no bytes/counters changed.
      }
      if (records + newlyDecoded.length > MAX_RECORDS) {
        joined.fill(0);
        blocked('RECORD_LIMIT');
      }
      const rest = Buffer.from(joined.subarray(offset));
      joined.fill(0);
      carry.fill(0);
      carry = rest;
      pending.push(...newlyDecoded);
      records += newlyDecoded.length;
      bytesReceived += chunk.length;
      return status();
    },
    take(limit = MAX_PENDING) {
      if (state !== 'ACTIVE' && state !== 'ENDED') fail('NOT_READABLE');
      if (!Number.isSafeInteger(limit) || limit < 1 || limit > MAX_PENDING)
        fail('TAKE_LIMIT');
      return pending.splice(0,limit);
    },
    finish() {
      if (state !== 'ACTIVE') fail('NOT_ACTIVE');
      if (carry.length !== 0 || records === 0) blocked('TRUNCATED_OR_EMPTY');
      state='ENDED';
      return status();
    },
    cancel() {
      if (state === 'FAILED') fail('NOT_CANCELLABLE');
      if (state !== 'CANCELLED') {wipe(); state='CANCELLED';}
      return status();
    },
    status
  });
}
